import{_ as s,c as a,o,ag as t}from"./chunks/framework.DRADY2L-.js";const u=JSON.parse('{"title":"Supervisor MCP Server","description":"","frontmatter":{},"headers":[],"relativePath":"mcp_servers/supervisor/index.md","filePath":"mcp_servers/supervisor/index.md"}'),i={name:"mcp_servers/supervisor/index.md"};function n(r,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="supervisor-mcp-server" tabindex="-1">Supervisor MCP Server <a class="header-anchor" href="#supervisor-mcp-server" aria-label="Permalink to &quot;Supervisor MCP Server&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Hybrid HTTP/MCP service that orchestrates multiple specialised agents and MCP tools using LangGraph’s supervisor workflow. It runs a FastAPI app (for <code>/health</code> and SSE transport) and an MCP server (<code>Supervisor MCP Server</code>) that exposes high-level tools to coordinate downstream agents.</p><p>Unlike the other services, this server does not have a dedicated <code>*.mcp.yml</code> entry; it is typically run as part of the BuddAI stack or invoked manually when the orchestration layer is required.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><ul><li><strong><code>main.py</code></strong> – boots FastAPI + FastMCP, registers the public tools, and streams progress updates back to the caller. Loads agents during application lifespan and exposes <code>/health</code> for container health checks.</li><li><strong><code>loaders/agent_loader.py</code></strong> – discovers <code>agents/*.agent.yml</code>, builds LangChain agents with <code>create_react_agent</code>, and compiles a LangGraph supervisor with MongoDB-backed checkpoints.</li><li><strong><code>loaders/mcp_loader.py</code></strong> – reads every <code>mcp_servers/*.mcp.yml</code>, initialises a <code>MultiServerMCPClient</code>, and hydrates MCP tools for use inside LangGraph agents.</li><li><strong><code>helpers/extract_content.py</code></strong> – parses streamed LangGraph events to surface agent names and the final message for MCP responses.</li><li><strong><code>Dockerfile</code></strong> – Python 3.13 build that vendors dependencies, copies agent definitions and MCP configs, installs <code>docker</code> + <code>curl</code> for nested tool execution, and defines a <code>HEALTHCHECK</code> hitting <code>/health</code>.</li></ul><h2 id="exposed-mcp-tools" tabindex="-1">Exposed MCP tools <a class="header-anchor" href="#exposed-mcp-tools" aria-label="Permalink to &quot;Exposed MCP tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Input</th></tr></thead><tbody><tr><td><code>run_supervisor</code></td><td>Orchestrates a conversation among configured agents, streaming progress via <code>ctx.report_progress</code>. Returns the supervisor’s final message content.</td><td><code>prompt</code>, optional <code>user_id</code> (defaults to last caller).</td></tr><tr><td><code>notify_user</code></td><td>Generates a notification message for an agenda reminder, adapting tone based on snooze counters.</td><td><code>agenda</code> dict with <code>rememberText</code> and <code>status</code>.</td></tr></tbody></table><p>Both tools rely on the supervisor graph created during startup. <code>run_supervisor</code> pulls agent definitions and underlying MCP tools; <code>notify_user</code> reuses the same supervisor to produce a natural-language reminder.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Environment variables consumed by various subsystems:</p><ul><li><strong>MongoDB</strong>: <code>MONGO_URI</code> – required for LangGraph checkpointing (<code>MongoDBSaver</code>).</li><li><strong>LLM providers</strong>: whichever secrets <code>langchain</code> backends require (<code>ANTHROPIC_API_KEY</code>, <code>OPENAI_API_KEY</code>, <code>LANGFUSE_*</code>, etc.). These are passed through from <code>.env</code> via <code>dotenv</code>.</li><li><strong>MCP tool configs</strong>: <code>loaders/mcp_loader.py</code> reads every <code>*.mcp.yml</code> and substitutes <code>\${VAR}</code> with environment values. Ensure all downstream services have their variables available when the supervisor starts, as it may spin up Docker containers for them.</li><li><strong>Debugging</strong>: use <code>LOG_LEVEL</code> and <code>LANGCHAIN_HANDLER</code> env vars as needed; FastAPI logging is silenced for <code>/health</code> by the middleware.</li></ul><h3 id="runtime-expectations" tabindex="-1">Runtime expectations <a class="header-anchor" href="#runtime-expectations" aria-label="Permalink to &quot;Runtime expectations&quot;">​</a></h3><ul><li>MongoDB must allow the creation of <code>supervisor_memory_checkpoints</code> and <code>supervisor_memory_writes</code> collections.</li><li>Agent configuration files (<code>agents/*.agent.yml</code>) must exist and reference valid tools/LLM models.</li><li>Docker-in-Docker access is required if agents invoke MCP tools defined as Docker commands (the container installs the Docker CLI for that reason).</li></ul><h2 id="running-locally" tabindex="-1">Running locally <a class="header-anchor" href="#running-locally" aria-label="Permalink to &quot;Running locally&quot;">​</a></h2><ol><li>Install Python ≥ 3.11 and create a virtualenv.</li><li><code>pip install -r requirements</code> equivalent: <code>pip install -e .</code> from <code>mcp_servers/supervisor</code> using the provided <code>pyproject.toml</code>/<code>uv.lock</code>.</li><li>Populate <code>.env</code> with <code>MONGO_URI</code>, LLM keys (OpenAI, Anthropic, etc.), and all secrets required by downstream MCP servers.</li><li>Ensure <code>agents/*.agent.yml</code> is populated and references the correct agent models/tools.</li><li>Start the service with <code>python main.py</code>. FastAPI listens on <code>:8000</code> and the MCP interface is exposed via Server-Sent Events (<code>FastMCP.sse_app()</code>), which clients like <code>langchain_mcp_adapters</code> can connect to.</li></ol><h2 id="docker-usage" tabindex="-1">Docker usage <a class="header-anchor" href="#docker-usage" aria-label="Permalink to &quot;Docker usage&quot;">​</a></h2><p>Build the image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buddai/mcp-supervisor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>(Execute from the repository root so the Dockerfile paths resolve.)</p><p>Run with the required secrets mounted:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8000:8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> buddai_net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MONGO_URI=mongodb://mongo:27017/buddai</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OPENAI_API_KEY=...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ANTHROPIC_API_KEY=...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> other-mcp.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  buddai/mcp-supervisor</span></span></code></pre></div><p>The container publishes <code>/health</code> for orchestration and streams MCP responses over HTTP (<code>/</code>).</p><h2 id="development-notes" tabindex="-1">Development notes <a class="header-anchor" href="#development-notes" aria-label="Permalink to &quot;Development notes&quot;">​</a></h2><ul><li>Agents are re-created at startup; changes to <code>agents/*.agent.yml</code> require a restart.</li><li><code>loaders/mcp_loader.py</code> closes over a global <code>MultiServerMCPClient</code>; ensure Docker sockets and network permissions allow it to launch other MCP services when running in a restricted environment.</li><li>The Dockerfile copies <code>mcp_servers/*.mcp.yml</code> into the image so the supervisor has access to local tool definitions even in isolation.</li><li>Legacy tests live under <code>old_test/</code>; they reference outdated APIs and serve mainly as historical context.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Supervisor fails to start</strong>: check that MongoDB is reachable and that all referenced <code>agents/*.agent.yml</code> files exist and parse correctly.</li><li><strong>Tool launch errors</strong>: confirm Docker is available inside the container and that each referenced MCP service image exists (<code>docker pull</code> as needed).</li><li><strong>LLM authentication errors</strong>: ensure environment variables for chosen providers are passed through; <code>init_chat_model</code> uses <code>configurable_fields</code> to set model/temperature per agent.</li><li><strong>No progress updates</strong>: verify that <code>ctx.report_progress</code> is called—logs showing agent names should appear; adjust <code>helpers/extract_content</code> if event formats change.</li></ul>`,27)])])}const g=s(i,[["render",n]]);export{u as __pageData,g as default};
